INSERT INTO cms_page (title, root_template, identifier, content_heading, content, is_active, sort_order, creation_time, update_time) SELECT 'Class Reschedule Request','one_column','class-reschedule.html','Class Reschedule Request',,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='class-reschedule.html') t);
INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='class-reschedule.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);
